import{_ as e,o as s,c as i,a5 as t}from"./chunks/framework.BmD0ICqc.js";const r="/study/images/data/binary-file-validation.svg",f=JSON.parse('{"title":"バイナリファイルの読み取り前に範囲を検査する","description":"","frontmatter":{"title":"バイナリファイルの読み取り前に範囲を検査する","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"data","summary":"バイナリファイルの識別子・版・件数・オフセット・長さを検査する順序を追う。整数の折り返し、展開時の上限、内容の検証を扱う。","aliases":["バイナリファイル","範囲検査","バイナリパーサー","binary validation","magic number","オフセット","bounds check","integer overflow","整数オーバーフロー"],"verification":"C++草案、MicrosoftのPE仕様、IETFの圧縮・認証仕様に照合"}},"headers":[],"relativePath":"data/binary-file-validation.md","filePath":"data/binary-file-validation.md"}'),n={name:"data/binary-file-validation.md"};function l(h,a,d,o,p,c){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="バイナリファイルの読み取り前に範囲を検査する" tabindex="-1">バイナリファイルの読み取り前に範囲を検査する <a class="header-anchor" href="#バイナリファイルの読み取り前に範囲を検査する" aria-label="Permalink to &quot;バイナリファイルの読み取り前に範囲を検査する&quot;">​</a></h1><p>ゲームがパックファイルからアセットを読むとき、最初に読むのは索引です。索引に「先頭から60バイトの位置に、4バイトのデータがある」と書かれていれば、その範囲を取り出します。更新途中のファイルや壊れたファイルでは、同じ欄がファイルの末尾を指し越すこともあります。件数や長さは、対応する範囲を確かめてからメモリ確保や読み取りに使います。<a href="/study/game/asset-pack-files.html">ゲームのアセットパック</a> · <a href="/study/os/file-read-journey.html">ファイル読み取りと短い読み取り</a></p><h2 id="最小のヘッダーから読む" tabindex="-1">最小のヘッダーから読む <a class="header-anchor" href="#最小のヘッダーから読む" aria-label="Permalink to &quot;最小のヘッダーから読む&quot;">​</a></h2><p>実践用の<code>SPAK</code>形式は4バイトの識別子<code>SPAK</code>、4バイトのバージョン、4バイトの件数から始まります。その後に24バイトの索引項目が件数分並びます。各項目はNULで埋めた16バイトのASCII名、4バイトのオフセット、4バイトの長さで構成します。数値欄は符号なし32ビットのリトルエンディアンで、オフセットはファイルの先頭から数えます。<a href="https://eel.is/c++draft/cstdint.syn" target="_blank" rel="noreferrer">C++の固定幅整数型</a> · <a href="/study/data/integer-bits-and-bytes.html">整数とバイト列の読み方</a></p><p>まず12バイトが存在することを確かめ、識別子を照合します。次に版を確認し、その版が定める位置・幅・バイト順で以降の欄を読みます。C++の<code>struct</code>をそのままファイルに重ねると、処理系のパディングやエンディアンに読み方が依存します。保存形式が定めたバイト列から、一つずつ値を組み立てます。<a href="/study/runtime/cpp-internals/memory-layout.html">構造体とメモリレイアウト</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/debug/pe-format#optional-header-image-only" target="_blank" rel="noreferrer">MicrosoftのPE仕様にあるヘッダーと索引の検査</a></p><h2 id="件数を掛ける前に、入る件数を求める" tabindex="-1">件数を掛ける前に、入る件数を求める <a class="header-anchor" href="#件数を掛ける前に、入る件数を求める" aria-label="Permalink to &quot;件数を掛ける前に、入る件数を求める&quot;">​</a></h2><p>ファイル全体が64バイトなら、12バイトのヘッダーより後には52バイトあります。24バイトの索引項目は最大で<code>52 / 24 = 2</code>件入ります。件数が3なら、この時点で入力を拒否できます。件数が2なら、索引の終端は<code>12 + 2 * 24 = 60</code>です。</p><p>固定幅の型で先に<code>count * 24</code>を求めると、件数が極端に大きい場合に結果が折り返すことがあります。先に<code>count &lt;= (file_size - header_size) / entry_size</code>を確認すれば、その後の掛け算と加算はファイルサイズの範囲に収まります。これとは別に、アプリで扱える最大件数や索引サイズを設定します。ファイル上で成立する件数でも、そのまま全件の管理領域を確保できるとは限りません。<a href="https://eel.is/c++draft/basic.fundamental#2" target="_blank" rel="noreferrer">C++の整数演算の範囲</a></p><h2 id="データの開始位置と長さを順に調べる" tabindex="-1">データの開始位置と長さを順に調べる <a class="header-anchor" href="#データの開始位置と長さを順に調べる" aria-label="Permalink to &quot;データの開始位置と長さを順に調べる&quot;">​</a></h2><p>オフセットと長さを<code>offset</code>と<code>length</code>とすると、対象は<code>[offset, offset + length)</code>です。右端の位置は範囲に含めません。次の順番なら、検査中に危険な加算をせず、<code>file_size - offset</code>が負になる条件も避けられます。</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;cstdint&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint64_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> file_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint64_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> offset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint64_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> length</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> offset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> file_size </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> length </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> file_size </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> offset;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>&amp;&amp;</code>は左側が成立したときだけ右側を評価します。実践の壊れた索引と同じく、開始位置を<code>0xfffffffe</code>、長さを<code>4</code>として32ビットの符号なし型で足すと、値は<code>2</code>へ折り返します。この和だけをファイルサイズと比べると、範囲外の開始位置を見落とします。検査を通した後に配列添字やAPIの引数へ変換する場合も、その型が値を表せることを確かめます。<a href="https://eel.is/c++draft/expr.log.and" target="_blank" rel="noreferrer">C++の論理積の評価順序</a> · <a href="https://eel.is/c++draft/basic.fundamental#2" target="_blank" rel="noreferrer">C++の符号なし整数演算</a></p><figure class="study-figure"><img src="`+r+'" alt="64バイトのファイルを例に、0から12までのヘッダー、12から60までの2件の索引、60から64までのデータを示す。60から4バイトは収まる。59から1バイトは索引を指す。62から4バイトはファイルの末尾を越える。" width="760" height="492" loading="lazy"><figcaption>64バイトのファイルで、データ領域の始点と末尾をそれぞれ確認します。帯の幅は読みやすさのため調整しています。<a href="/study/images/data/binary-file-validation.svg" target="_blank" rel="noopener noreferrer">範囲検査の図を拡大</a></figcaption></figure><p>ファイルに収まると分かっても、形式が指定した領域かを確認します。図の<code>[59, 60)</code>はファイル内の索引を指します。データを読むなら、<code>offset &gt;= 60</code>も必要です。長さ0を許すか、データ範囲の共有を許すか、同じ名前が現れた場合をどう扱うかも形式で決めます。実践では索引がデータの開始位置順に並ぶと定め、直前の終端が次の開始位置を越えたら拒否します。名前は小文字の英字・数字・<code>_</code>・<code>-</code>からなる1～15文字で、残りのバイトをNULで埋め、重複を拒否します。<a href="/study/game/asset-pack-files.html">アセットパックの索引とデータ</a></p><h2 id="構造の検査から、内容と資源量の検査へ" tabindex="-1">構造の検査から、内容と資源量の検査へ <a class="header-anchor" href="#構造の検査から、内容と資源量の検査へ" aria-label="Permalink to &quot;構造の検査から、内容と資源量の検査へ&quot;">​</a></h2><p>索引から切り出した範囲が正しくても、画像ならピクセルの形式、メッシュなら頂点数とインデックスなどを、そのデータ形式の規則で検査します。たとえばメッシュのインデックスが参照する頂点番号は、読み込んだ頂点数より小さい必要があります。ファイルを分割して読む場合は、実際に読めたバイト数も確認します。ファイルのサイズを取得してから読み取るまでに内容が変わり得る構成なら、同じ版のデータを読み続けられるよう、読み取り中の更新を防ぐなどの手当てをします。<a href="/study/os/file-read-journey.html">ファイル読み取りでの実際の読み取り量</a> · <a href="/study/game/asset-loading.html">アセットを利用可能にする条件</a></p><p>圧縮データには、入力範囲の上限、出力バイト数の上限、展開器の作業メモリの上限を設けます。ヘッダーの展開後サイズを検査してから確保し、展開中も実際の出力量を制限します。Zstandardの仕様でも、フレームが要求する展開用ウィンドウが実装の許容範囲を超えたら拒否できます。<a href="https://www.rfc-editor.org/rfc/rfc8878.html#name-window_descriptor" target="_blank" rel="noreferrer">RFC 8878のZstandardフレーム仕様</a></p><p>チェックサムは保存や転送で起きた破損を検出する手掛かりです。配布元を確かめるには、信頼済みの公開鍵でデジタル署名を検証する方法があります。秘密鍵を共有する構成では、メッセージ認証コード（MAC）で共有鍵を持つ側が認証したデータかを確かめられます。照合に成功したファイルも、受け入れる版や展開量など、読み手の条件を満たすか検査します。<a href="https://www.rfc-editor.org/rfc/rfc1952.html#section-2.3.1" target="_blank" rel="noreferrer">RFC 1952のCRC32</a> · <a href="https://csrc.nist.gov/pubs/fips/186-5/final" target="_blank" rel="noreferrer">NISTのデジタル署名仕様</a> · <a href="https://www.rfc-editor.org/rfc/rfc2104.html#section-1" target="_blank" rel="noreferrer">RFC 2104のメッセージ認証コード</a></p><p>実践では、パックを生成して名前からアセットを読み、壊れた索引がデータの読み取り前に拒否される様子を確認できます。<a href="/study/practice/io/asset-pack-observation.html">C++でアセットパックを観察する</a></p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/data/hashes-and-checksums.html">ハッシュとチェックサム</a></li></ul>',21)])])}const g=e(n,[["render",l]]);export{f as __pageData,g as default};
